/** `spec/m/meta.tn`'s own header: `!!id:"https://tson.io/2026/40/m/meta.tn?sha256=291ddaf37566f9f084515d09626f1855d05f2cfb9413e3ce0073323f4933ddcd"` */
export const META_TN =
  '!!id:"https://tson.io/2026/40/m/meta.tn?sha256=291ddaf37566f9f084515d09626f1855d05f2cfb9413e3ce0073323f4933ddcd"\n@doc:"""\n  The TSON kernel: the vocabulary every schema is written in. Its root holds the\n  names an author writes: `text`, `integer`, `int64`, `boolean`, `bytes`, `iri`,\n  `iri_reference`, `regex`, `void`, `enum`, `set<T>`, `@doc` and the `schema`\n  tag. Its maps hold the machinery behind them: the type system\n  (`meta`), the atom constructors (`numeric`, `unicode`, `net`, `binary`) and\n  the classifying annotations (`atom`).\n\n  Every processor pre-loads it ([TSON-SCHEMA] §3.4). §9 lists what each bundled\n  document holds, and §5 is the grammar the examples here are written in.\n  """\n!schema {\n\n  numeric => !schema {\n    @doc:"""\n      A fixed width for an integer: `size: { bits: 32  signed: true }`. Signed\n      n-bit is [-2^(n-1), 2^(n-1)-1], unsigned [0, 2^n-1]. `bits` is above zero.\n      """\n    integer_size => {\n      bits:    integer\n      signed:  boolean\n    }\n\n    @doc:"The members of an integer_type."\n    integer_member_set => !meta.set_type { element_type: integer  min_items: 1 }\n\n    @doc:"""\n      The constructor of `integer`. An author refines the instance,\n      `age => !integer ^ { min: 0  max: 150 }`, with bounds, a width (`size`), a\n      step (`multiple_of`) or the admitted values (`members`).\n\n      A bound lies inside the range `size` gives, and the lower bound does not\n      exceed the upper. `multiple_of` is strictly positive and tests the value\'s\n      magnitude, so -30 is a multiple of 15. Every member satisfies the other\n      facets on the same body ([TSON-SCHEMA] §5.5; §5.7 for what a refinement\n      may tighten).\n      """\n    integer_type => meta.atom & {\n      size?: numeric.integer_size\n      ( min: integer | exclusive_min: integer )?\n      ( max: integer | exclusive_max: integer )?\n      multiple_of?: integer\n      members?:     numeric.integer_member_set\n    }\n\n    @doc:"""\n      A non-negative `int64`: the type of every facet that counts something, a\n      length, an item count, a digit count.\n      """\n    count => !int64 ^ { min: 0 }\n  }\n\n  unicode => !schema {\n    @doc:"The members of a text_type."\n    text_member_set => !meta.set_type { element_type: text  min_items: 1 }\n\n    @doc:"""\n      The constructor of `text`. An author refines the instance:\n      `name => !text ^ { min_length: 1  max_length: 80 }`,\n      `code => !text ^ { pattern: "[A-Z]{3}" }`. Lengths count code points,\n      `pattern` is an I-Regexp (RFC 9485) the whole value matches, and `members`\n      lists the admitted strings.\n\n      A value is its token\'s text put into `normalization`\'s form, and every\n      other facet, and every comparison of two values, judges that value and\n      never the spelling ([TSON-SCHEMA] §5.5; §5.7 for what a refinement may\n      tighten).\n      """\n    text_type => meta.atom & {\n      min_length?:    numeric.count\n      max_length?:    numeric.count\n      length?:        numeric.count\n      pattern?:       regex\n      members?:       unicode.text_member_set\n      normalization?: unicode.normalization ~ NONE\n    }\n\n    @doc:"""\n      What a profile\'s Start or Continue set is drawn from (UAX #31): XID_Start\n      and XID_Continue, ID_Start and ID_Continue, their ASCII members (Start A-Z\n      a-z, Continue adding 0-9 and "_"), or the empty set.\n      """\n    identifier_base => !enum [XID ID ASCII NONE]\n\n    @doc:"""\n      The form a text value is put into. NONE keeps the text as written.\n      NFKC_CASEFOLD is toNFKC_Casefold. ASCII_CASEFOLD maps A-Z to a-z and\n      changes nothing else ([TSON-SCHEMA] §5.5).\n      """\n    normalization => !enum [NONE NFC NFKC NFKC_CASEFOLD ASCII_CASEFOLD]\n\n    @doc:"""\n      The constructor of an identifier family: a UAX #31 profile (R1), with\n      text_type\'s facets applied inside it. `meta.identifier` is the kernel\'s,\n      and a schema declares its own for another naming convention,\n      `snake => !unicode.identifier_type { start: ASCII  continue: ASCII }`:\n\n        identifier := Start Continue* (Medial Continue+)*\n        Start      := (start ∪ start_add) − exclude\n        Continue   := (continue ∪ continue_add) − exclude\n        Medial     := medial\n\n      `start_add`, `continue_add`, `medial` and `exclude` are each the set of\n      code points their text holds, and `medial` is disjoint from Start and\n      Continue. The profile judges the value, the text in its normalization\n      form. A join control (U+200C, U+200D) is admitted only in the contexts UTS\n      #39 §3.1.1.1 permits, whatever the profile ([TSON-DATA] §7.7,\n      [TSON-SCHEMA] §7.4).\n      """\n    identifier_type => unicode.text_type & atom.specification & {\n      spec?:          = "https://www.unicode.org/reports/tr31/"\n      start?:         unicode.identifier_base ~ XID\n      continue?:      unicode.identifier_base ~ XID\n      start_add?:     text\n      continue_add?:  text\n      medial?:        text\n      exclude?:       text\n      normalization?: unicode.normalization ~ NFC\n    }\n\n    @doc:"The constructor of `regex`: an I-Regexp (RFC 9485), kept as written."\n    regex_type => unicode.text_type & atom.specification & {\n      spec?:          = "https://www.rfc-editor.org/rfc/rfc9485"\n      normalization?: = NONE\n    }\n  }\n\n  net => !schema {\n    @doc:"The schemes an iri_type or uri_type admits."\n    scheme_set => !meta.set_type { element_type: net.scheme_name  min_items: 1 }\n\n    @doc:"A URI scheme (RFC 3986 §3.1), compared without case."\n    scheme_name => !unicode.identifier_type { start: ASCII  continue: ASCII\n      continue_add: "+-."  exclude: "_"  normalization: ASCII_CASEFOLD }\n\n    @doc:"""\n      The constructor of `iri` and `iri_reference` (RFC 3987). `schemes` lists\n      the admitted schemes, `web => !iri ^ { schemes: [https] }`, and a value\n      with no scheme is outside every list. `allow_relative` admits a relative\n      reference and `allow_fragment` a fragment. An IRI is judged through the\n      URI it maps to (RFC 3987 §3.1).\n      """\n    iri_type => unicode.text_type & atom.specification & {\n      spec?:           = "https://www.rfc-editor.org/rfc/rfc3987"\n      schemes?:        net.scheme_set\n      allow_relative?: boolean ~ true\n      allow_fragment?: boolean ~ true\n      normalization?:  = NONE\n    }\n\n  }\n\n  atom => !schema {\n    @doc:"""\n      A mixin for an atom constructor that follows a published specification:\n      `spec` is its IRI, which the constructor pins.\n      """\n    specification => { spec: iri }\n\n    @doc:"""\n      ISO/IEC 11404: whether the value space has an order relation. Written on\n      an atom, `@atom.ordering:TOTAL`.\n      """\n    ordering => @meta.annotation !enum [NONE PARTIAL TOTAL]\n\n    @doc:"""\n      ISO/IEC 11404: true when the value space has a least and a greatest value.\n      """\n    bounded => @meta.annotation boolean\n\n    @doc:"""\n      ISO/IEC 11404: true where a value is kept as written, false where it is\n      rounded to a grid.\n      """\n    exact => @meta.annotation boolean\n\n    @doc:"ISO/IEC 11404: marks a numeric type, written bare, `@atom.numeric`."\n    numeric => @meta.annotation void\n\n  }\n\n  @doc:"""\n    The type system: the constructors every type is built with, each named by\n    its path, `meta.record`.\n    """\n  meta => !schema {\n    @doc:"""\n      The root of the type system: every constructor IS-A `top` ([TSON-SCHEMA]\n      §4.1).\n      """\n    top       => abstract {}\n\n    @doc:"""\n      Where a type sits in the IS-A order. Derived, never written by a\n      declaration: `parents` is a parametric record\'s parents as written,\n      `supertypes` the closed IS-A chain, and `subtypes` its inverse\n      ([TSON-SCHEMA] §4.1, §8.1).\n      """\n    type_chain => {\n      parents?:    [meta.type_expr]\n      supertypes?: meta.set_type<meta.type_ref>\n      subtypes?:   meta.set_type<meta.type_ref>\n    }\n\n    @doc:"""\n      What every type\'s body is: `atom`, `product` and `sum` are its kinds, and\n      `chain` its place in the IS-A order ([TSON-SCHEMA] §4.1).\n      """\n    type      => abstract meta.top & {\n      chain?: meta.type_chain\n    }\n\n    @doc:"The kind of a scalar: a value written as one token."\n    atom      => abstract meta.type & {}\n\n    @doc:"The kind of a compound value: a record, an array, a map or a tuple."\n    product   => abstract meta.type & {\n      access_pattern: meta.product_access_type\n      size_type:      meta.product_size_type\n    }\n\n    @doc:"""\n      The kind of a value that is one of several types: a choice, a declared\n      type or a dependent type.\n      """\n    sum       => abstract meta.type & {}\n\n    @doc:"""\n      Another name for an entry: `user_id => uuid` makes `user_id` the same type\n      as `uuid` ([TSON-SCHEMA] §8.3).\n      """\n    alias => meta.top & {\n      target: meta.type_ref\n    }\n\n    @doc:"""\n      One entry of another schema under a name of this one: `order_v1 =>\n      !meta.extern { schema: "https://example.com/order-1.tn"  type: order }`\n      makes `order_v1` the same type as that schema\'s `order`. `type` is a name\n      in that schema\'s namespace; none of that schema\'s names enter this one. A\n      value at a position typed `order_v1` uses the names of its own schema\n      inside it ([TSON-SCHEMA] §5.13, §7.9).\n      """\n    extern => meta.top & {\n      schema: iri_reference\n      type:   text\n    }\n\n    @doc:"""\n      A parameter of a parametric record, `<T>`, or with a bound every argument\n      must IS-A, `<T: text>` ([TSON-SCHEMA] §5.10).\n      """\n    param => {\n      name:   meta.param_name\n      bound?: meta.type_ref\n    }\n\n    @doc:"The constructor of `void`: it admits only the void sentinel `_`."\n    void_type => meta.atom & {}\n\n    @doc:"""\n      The default name: XID_Start, then XID_Continue or `-`, in NFC. The type of\n      type, field and parameter names ([TSON-DATA] §7.7).\n      """\n    identifier => !unicode.identifier_type { continue_add: "-" }\n\n    @doc:"A type\'s name: a schema-map key, and a segment of a reference."\n    type_name  => meta.identifier\n\n    @doc:"A parameter\'s name."\n    param_name => meta.identifier\n\n    @doc:"How a product\'s parts are reached: by position, or by name."\n    product_access_type => !enum [INDEX NAMED]\n\n    @doc:"Whether a product\'s number of parts is fixed by its type."\n    product_size_type   => !enum [FIXED VARIABLE]\n\n    @doc:"""\n      What a field\'s `value` is for. FREE has none, DEFAULT is injected when the\n      field is omitted, written `~ value`, and FIXED is the only value the field\n      admits, written `= value` ([TSON-SCHEMA] §5.2).\n      """\n    field_role          => !enum [FREE DEFAULT FIXED]\n\n    @doc:"""\n      How a record may be realised, written as a mark: `pet => abstract { … }`\n      has no values of its own, `final { … }` admits no subtype, and OPEN is the\n      unmarked default ([TSON-SCHEMA] §5.2).\n      """\n    record_extension_type => !enum [ABSTRACT FINAL OPEN]\n\n    @doc:"""\n      Marks a type as meant for use as an annotation:\n      `title => @meta.annotation text` declares what `@title:"Order"` is read\n      against. An alias of `void`, so it carries no force ([TSON-SCHEMA] §6).\n      """\n    annotation => void\n\n    @doc:"""\n      Resolver-attached to an entry\'s key, never written: the application of a\n      parametric record the entry closes,\n      `{ head: pair  arguments: [text integer] }`\n      ([TSON-SCHEMA] §8.2).\n      """\n    application => @meta.annotation meta.apply\n\n    @doc:"""\n      Resolver-attached to an entry\'s key, never written: the incomplete entries\n      the entry\'s declaration completed, nearest first, each by its own name\n      past alias hops, so `tags => set<text>` carries\n      `{ of: [meta.set_type] }`. The names are text and not references: those\n      entries are in no resolved form ([TSON-SCHEMA] §8.1).\n      """\n    completion => @meta.annotation {\n      of: [text; 1..]\n    }\n\n    @doc:"""\n      One field of a record, the spelling `name?: type? ~ value`. `optional` is\n      the name\'s `?`, the key may be missing; `voidable` is the type\'s `?`, the\n      value may be `_`; `role` and `value` are the default after `~` or the\n      fixed value after `=`.\n\n      `value` is read against the type `type` names, and is present exactly when\n      `role` is not FREE. DEFAULT requires `optional`, and FIXED a field that is\n      not `voidable` ([TSON-SCHEMA] §5.2).\n      """\n    record_field => {\n      type:      meta.type_expr\n      optional?: boolean ~ false\n      voidable?: boolean ~ false\n      role?:     meta.field_role ~ FREE\n      value?:    type!\n    }\n\n    @doc:"""\n      A presence rule over a record\'s fields, written\n      `( min: integer | exclusive_min: integer )?`. `members` lists the options,\n      each the fields it holds: exactly one option is present, or at most one\n      where `optional`. `optional_members` names the members that may be missing\n      from a chosen option ([TSON-SCHEMA] §5.11).\n      """\n    field_group => {\n      members:           [[text; 1..]; 1..]\n      optional_members?: [text; 1..]\n      optional?:         boolean ~ false\n    }\n\n    @doc:"""\n      The fields of a record: each field\'s name mapped to its facts, in\n      declaration order.\n      """\n    field_map => !meta.map { key_type: text  value_type: meta.record_field  ordered: true }\n\n    @doc:"""\n      The constructor of every record type, written in braces:\n      `person => { name: text  age?: integer }`.\n\n      `fields` is flattened, a composition\'s fields being its operands\' and its\n      own. `parameters` makes it a parametric record, `<T> { item: T }`.\n      `extension` is its `abstract` or `final` mark, `discriminators` names the fields its\n      members are selected by, and `name_type` the type its field names are\n      values of ([TSON-SCHEMA] §5.2; §5.8 for composition, §5.10 for parametric\n      records).\n      """\n    record => meta.product & {\n      access_pattern?: meta.product_access_type = NAMED\n      size_type?:      meta.product_size_type = FIXED\n      parameters?:     [meta.param; 1..]\n      fields:          meta.field_map\n      groups?:         [meta.field_group]\n      extension?:      meta.record_extension_type ~ OPEN\n      discriminators?: [text; 1..]\n      name_type?:      meta.identifier_ref\n    }\n\n    @doc:"""\n      The constructor of `[T]`, with a size as `[T; 1..10]` and void elements as\n      `[T?]`. `ordered` says whether two values differing only in order are\n      distinct ([TSON-SCHEMA] §5.3).\n      """\n    array => meta.product & {\n      access_pattern?: meta.product_access_type = INDEX\n      size_type?:      meta.product_size_type = VARIABLE\n      element_type:    meta.type_expr\n      voidable?:       boolean ~ false\n      ordered?:        boolean ~ true\n      unique_items?:   boolean ~ false\n      min_items?:      numeric.count\n      max_items?:      numeric.count\n    }\n\n    @doc:"""\n      An array left open, its `element_type` absent: elements distinct, never\n      void, and their order no part of the value. It is no type; completing it\n      with the element type makes one, `meta.set_type<text>`, which is\n      `!meta.array { element_type: text  ordered: false  unique_items: true }`\n      ([TSON-SCHEMA] §5.5, §7.5).\n      """\n    set_type => !meta.array ^ { voidable: false  ordered: false  unique_items: true }\n\n    @doc:"""\n      The constructor of `{K => V}`, with void values as `{K => V?}`; a key is\n      never void. `ordered` is as `array`\'s, and false unless the map says\n      otherwise ([TSON-SCHEMA] §5.3).\n      """\n    map => meta.product & {\n      access_pattern?: meta.product_access_type = NAMED\n      size_type?:      meta.product_size_type = VARIABLE\n      key_type:        meta.type_ref\n      value_type:      meta.type_expr\n      voidable?:       boolean ~ false\n      ordered?:        boolean ~ false\n      min_items?:      numeric.count\n      max_items?:      numeric.count\n    }\n\n    @doc:"""\n      The constructor of a namespace type, a map keyed by names:\n      `api => !meta.namespace { key_type: meta.identifier  value_type: method }`,\n      and then a value of it, `orders => !api { place => { … } }`. A segment of\n      a qualified name selects a key of a namespace value, `orders.place`, and\n      of no other map ([TSON-SCHEMA] §4.1, §5.12).\n      """\n    namespace => meta.map & {\n      key_type:  meta.identifier_ref\n      voidable?: = false\n    }\n\n    @doc:"One position of a tuple: its type, and whether its value may be void."\n    tuple_element => {\n      element_type: meta.type_expr\n      voidable?:    boolean ~ false\n    }\n\n    @doc:"""\n      The constructor of `[A, B]`: a fixed sequence of positions, each with a\n      type of its own ([TSON-SCHEMA] §5.3).\n      """\n    tuple => meta.product & {\n      access_pattern?: meta.product_access_type = INDEX\n      size_type?:      meta.product_size_type = FIXED\n      elements:        [meta.tuple_element]\n    }\n\n    @doc:"The members of an enum_type."\n    enum_set => !meta.set_type { element_type: text  min_items: 1 }\n\n    @doc:"""\n      The constructor of an enum: a closed set of names, each a value of\n      `name_type`. An author writes `!enum [OPEN DONE]`, and constructs this\n      directly only for names of another naming convention ([TSON-SCHEMA]\n      §7.4).\n      """\n    enum_type => meta.atom & {\n      name_type: meta.identifier_ref\n      members:   meta.enum_set\n    }\n\n    @doc:"""\n      The constructor of `( A | B )`: a value of one of the variants. `disjoint`\n      is derived, never written: whether the variants are told apart by form,\n      without a tag ([TSON-SCHEMA] §5.4).\n      """\n    choice => meta.sum & {\n      variants:  [meta.type_expr]\n      disjoint?: boolean\n    }\n\n    @doc:"""\n      An author\'s assertion that a choice\'s variants are told apart by form,\n      checked against the derived `disjoint` ([TSON-SCHEMA] §5.4).\n      """\n    disjoint => @meta.annotation void\n\n    @doc:"""\n      The open sum: a value names its own type by its tag, among the types of\n      the closure ([TSON-SCHEMA] §7.8).\n      """\n    declared_type => meta.sum & {}\n\n    @doc:"""\n      A value of any type the closure declares, named by its tag. What a schema\n      map\'s entries are.\n      """\n    declared => !meta.declared_type {}\n\n    @doc:"""\n      A value is read against the type the sibling field `on` names. Written in\n      place at a record field\'s `type`, `kind!` in source ([TSON-SCHEMA] §5.2).\n      """\n    dependent => final meta.sum & { on: text }\n\n    @doc:"""\n      An application, `box<T>` in source. Written in place it stands only inside\n      a parametric record, with one of that record\'s parameters among its\n      arguments;\n      closed, it is the value of `@meta.application` ([TSON-SCHEMA] §5.10).\n      """\n    apply => final meta.type & {\n      head:      meta.type_ref\n      arguments: [meta.type_ref; 1..]\n    }\n\n    @doc:"""\n      A name held in a slot, written `handler: meta.ref<method>`. It names an\n      entry whose value\'s type, past alias hops, is `of` or IS-A it: where `of`\n      is a constructor the names are types\', and otherwise they are values\'\n      ([TSON-SCHEMA] §4.2, §5.12).\n      """\n    ref => meta.atom & {\n      of: meta.type_ref\n    }\n\n    @doc:"A slot holding a type\'s name."\n    type_ref => !meta.ref { of: meta.type }\n\n    @doc:"""\n      A slot holding the name of an identifier family, as a `name_type` does.\n      """\n    identifier_ref => !meta.type_ref ^ { of: unicode.identifier_type }\n\n    @doc:"""\n      A type written where it is used, `tags: [text]`, and not declared under a\n      name ([TSON-SCHEMA] §4.2).\n      """\n    type_inline => { of: meta.type }\n\n    @doc:"What a type slot holds: a type\'s name, or a type written in place."\n    type_expr => @meta.disjoint ( meta.type_ref | meta.type_inline )\n\n    @doc:"""\n      A schema map: each name mapped to the type or value its entry resolves to\n      ([TSON-SCHEMA] §2.1, §8.1).\n      """\n    schema => !meta.namespace { key_type: meta.type_name  value_type: meta.declared }\n  }\n\n  binary => !schema {\n    @doc:"RFC 4648\'s base encodings; HEX is its base16."\n    bytes_encoding => !enum [BASE64 BASE64URL BASE32 HEX]\n\n    @doc:"""\n      The constructor of `bytes`. The value is the octets: equality and the\n      length facets are over octets, never a spelling, so\n      `sha256 => !bytes ^ { length: 32 }` is 32 octets. `encoding` picks the\n      alphabet a text encoding spells them in and changes no value; another\n      alphabet is another instance, `!binary.bytes_type { encoding: HEX }`\n      ([TSON-SCHEMA] §5.5).\n      """\n    bytes_type => meta.atom & {\n      encoding?:   binary.bytes_encoding ~ BASE64\n      length?:     numeric.count\n      min_length?: numeric.count\n      max_length?: numeric.count\n    }\n  }\n\n  @doc:"""\n    The absence of a value, written `_` ([TSON-DATA] §2.9, [TSON-SCHEMA] §7.6).\n    """\n  void => !meta.void_type {}\n\n  @doc:"`true` or `false`."\n  boolean => !enum [true false]\n\n  @doc:"""\n    An integer of any size. Refine it for a range or a width:\n    `age => !integer ^ { min: 0  max: 150 }` ([TSON-SCHEMA] §5.5).\n    """\n  @atom.ordering:TOTAL @atom.bounded:false @atom.exact:true @atom.numeric\n  integer => !numeric.integer_type {}\n\n  @doc:"Signed 64-bit integer."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  int64 => !integer ^ { size: { bits: 64  signed: true } }\n\n  @doc:"""\n    Unicode text. Refine it to constrain it:\n    `name => !text ^ { min_length: 1  max_length: 80 }` ([TSON-SCHEMA] §5.5).\n    """\n  @atom.ordering:NONE @atom.bounded:false\n  text => !unicode.text_type {}\n\n  @doc:"""\n    An octet sequence, written in base64 in TSON text. A digest is\n    `sha256 => !bytes ^ { length: 32 }`, the length counting octets ([TSON-DATA]\n    §5.3).\n    """\n  @atom.ordering:NONE @atom.bounded:false\n  bytes => !binary.bytes_type {}\n\n  @doc:"An IRI-reference (RFC 3987 §2.2): an IRI or a relative reference."\n  @atom.ordering:NONE @atom.bounded:false\n  iri_reference => !net.iri_type {}\n\n  @doc:"An IRI (RFC 3987 §2.2): the scheme is required."\n  @atom.ordering:NONE @atom.bounded:false\n  iri => !iri_reference ^ { allow_relative: false }\n\n  @doc:"A regular expression in I-Regexp (RFC 9485), the type of a `pattern`."\n  @atom.ordering:NONE @atom.bounded:false\n  regex => !unicode.regex_type {}\n\n  @doc:"""\n    Documentation for a declaration, a field or a document, written before it.\n    The text is CommonMark 0.31.2, with no extensions, and raw HTML in it is\n    never executed ([TSON-SCHEMA] §6).\n    """\n  doc => @meta.annotation text\n\n  @doc:"""\n    An enum over identifiers, its `members` absent: `status => !enum [OPEN\n    DONE]` completes it, `!meta.enum_type { name_type: meta.identifier  members:\n    [OPEN DONE] }`. It is no type, so a field holding an enum type is typed\n    `meta.enum_type` ([TSON-SCHEMA] §5.5, §7.4).\n    """\n  enum => !meta.enum_type ^ { name_type: meta.identifier }\n\n  @doc:"""\n    `set<T>`: a collection of distinct elements whose order is no part of its\n    value, `tags: set<text>`. Another name for `meta.set_type`, which `set<T>`\n    completes ([TSON-SCHEMA] §7.5).\n    """\n  set => meta.set_type\n\n  @doc:"""\n    The tag of a schema map: a schema document\'s root is `!schema { … }`, and so\n    is a map nested as an entry, `geo => !schema { … }` ([TSON-SCHEMA] §2.1).\n    """\n  schema => meta.schema\n}\n';

/** `spec/m/numeric.tn`'s own header: `!!id:"https://tson.io/2026/40/m/numeric.tn?sha256=0337c18854a0e689ce53d9cae47e1cfd32bd54026acd6a3bac9abae358cb86f7"` */
export const NUMERIC_TN =
  '!!id:"https://tson.io/2026/40/m/numeric.tn?sha256=0337c18854a0e689ce53d9cae47e1cfd32bd54026acd6a3bac9abae358cb86f7"\n!!import:"https://tson.io/2026/40/m/meta.tn?sha256=291ddaf37566f9f084515d09626f1855d05f2cfb9413e3ce0073323f4933ddcd"\n@doc:"""\n  The TSON numeric library: the exact `number` and `rational`, `complex`, the\n  sized integers `int8` to `uint256` and the IEEE 754 `float32` and `float64`. A\n  schema imports it, or core.tn, to write them ([TSON-DATA] §5.6, [TSON-SCHEMA]\n  §5.5).\n\n  Shared by every family here and in temporal.tn: a lower bound does not exceed\n  the upper; `multiple_of` is strictly positive and tests the value\'s magnitude;\n  every member satisfies the other facets on the same body.\n  """\n!schema {\n  @doc:"""\n    The numeric constructors and their facet vocabulary, each named by its path,\n    `numeric.decimal_type`.\n    """\n  numeric => !schema {\n    @doc:"""\n      IEEE 754-2019 interchange formats. The decimal formats are base-10\n      floating point, approximate, and are not `decimal_type`\'s exact decimals.\n      """\n    ieee_format => !enum [\n      BINARY16 BINARY32 BINARY64 BINARY128 BINARY256\n      DECIMAL32 DECIMAL64 DECIMAL128\n    ]\n\n    @doc:"""\n      The constructor of `float32` and `float64`. An approximate value: the\n      receiver rounds it onto the IEEE 754-2019 grid `format` names, to nearest,\n      ties to even. The value set is that grid with signed zeros, subnormals,\n      the two infinities and the canonical quiet NaN ([TSON-DATA] §5.6), and the\n      `allow_` facets exclude those.\n\n      A bound is an exact `number`, judged against the value as written, before\n      rounding: it orders the infinities and admits no NaN, so `allow_nan`\n      decides NaN only where no bound is written ([TSON-SCHEMA] §5.5).\n      """\n    float_type => meta.atom & atom.specification & {\n      spec?:                = "https://ieeexplore.ieee.org/document/8766229"\n      format:               numeric.ieee_format\n      ( min: number | exclusive_min: number )?\n      ( max: number | exclusive_max: number )?\n      allow_nan?:           boolean ~ true\n      allow_infinity?:      boolean ~ true\n      allow_subnormal?:     boolean ~ true\n      allow_negative_zero?: boolean ~ true\n    }\n\n    @doc:"The members of a decimal_type."\n    decimal_member_set => !meta.set_type { element_type: number  min_items: 1 }\n\n    @doc:"""\n      The constructor of `number`. An author refines the instance:\n      `price => !number ^ { min: 0  fraction_digits: 2 }`. Exact: nothing is\n      rounded, and scale is no part of the value, so `1`, `1.0` and `1.00` are\n      one value. `total_digits` counts significant digits and `fraction_digits`\n      digits after the point ([TSON-SCHEMA] §5.5).\n      """\n    decimal_type => meta.atom & {\n      ( min: number | exclusive_min: number )?\n      ( max: number | exclusive_max: number )?\n      multiple_of?:     number\n      total_digits?:    numeric.count\n      fraction_digits?: numeric.count\n      members?:         numeric.decimal_member_set\n    }\n\n    @doc:"""\n      The constructor of `rational`. The value is the fraction: `2/4` and `1/2`\n      are one value. The denominator is positive.\n      """\n    rational_type => meta.atom & {\n      ( min: rational | exclusive_min: rational )?\n      ( max: rational | exclusive_max: rational )?\n      multiple_of?: rational\n    }\n\n    @doc:"""\n      The type of a complex value\'s parts. A refinement moves `component` only\n      to a member whose value set is inside the source\'s: INTEGER ⊂ NUMBER ⊂\n      RATIONAL and FLOAT32 ⊂ FLOAT64, the two families incomparable.\n      """\n    complex_component => !enum [INTEGER NUMBER RATIONAL FLOAT32 FLOAT64]\n\n    @doc:"""\n      The constructor of `complex`: a pair of components, the real and imaginary\n      parts, both of the type `component` names.\n      """\n    complex_type => meta.atom & {\n      component?: numeric.complex_component ~ NUMBER\n    }\n  }\n\n  @doc:"""\n    An exact decimal number of any magnitude and precision, with no infinities\n    and no NaN. Refine it to constrain it:\n    `price => !number ^ { min: 0  fraction_digits: 2 }`.\n    """\n  @atom.ordering:TOTAL @atom.bounded:false @atom.exact:true @atom.numeric\n  number => !numeric.decimal_type {}\n\n  @doc:"An exact fraction of two integers."\n  @atom.ordering:TOTAL @atom.bounded:false @atom.exact:true @atom.numeric\n  rational => !numeric.rational_type {}\n\n  @doc:"A complex number: a real and an imaginary part, each an exact `number`."\n  @atom.ordering:NONE @atom.bounded:false @atom.numeric\n  complex => !numeric.complex_type {}\n\n  @doc:"Signed 8-bit integer (-128 to 127)."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  int8 => !integer ^ { size: { bits: 8  signed: true } }\n\n  @doc:"Signed 16-bit integer."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  int16 => !integer ^ { size: { bits: 16  signed: true } }\n\n  @doc:"Signed 32-bit integer."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  int32 => !integer ^ { size: { bits: 32  signed: true } }\n\n  @doc:"Signed 128-bit integer."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  int128 => !integer ^ { size: { bits: 128  signed: true } }\n\n  @doc:"Signed 256-bit integer."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  int256 => !integer ^ { size: { bits: 256  signed: true } }\n\n  @doc:"Unsigned 8-bit integer (0 to 255)."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  uint8 => !integer ^ { size: { bits: 8  signed: false } }\n\n  @doc:"Unsigned 16-bit integer."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  uint16 => !integer ^ { size: { bits: 16  signed: false } }\n\n  @doc:"Unsigned 32-bit integer."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  uint32 => !integer ^ { size: { bits: 32  signed: false } }\n\n  @doc:"Unsigned 64-bit integer."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  uint64 => !integer ^ { size: { bits: 64  signed: false } }\n\n  @doc:"Unsigned 128-bit integer."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  uint128 => !integer ^ { size: { bits: 128  signed: false } }\n\n  @doc:"Unsigned 256-bit integer."\n  @atom.ordering:TOTAL @atom.bounded:true @atom.exact:true @atom.numeric\n  uint256 => !integer ^ { size: { bits: 256  signed: false } }\n\n  @doc:"IEEE 754 binary32: approximate, a value being rounded onto its grid."\n  @atom.ordering:PARTIAL @atom.bounded:false @atom.exact:false @atom.numeric\n  float32 => !numeric.float_type { format: BINARY32 }\n\n  @doc:"IEEE 754 binary64: approximate, a value being rounded onto its grid."\n  @atom.ordering:PARTIAL @atom.bounded:false @atom.exact:false @atom.numeric\n  float64 => !numeric.float_type { format: BINARY64 }\n}\n';

/** `spec/m/temporal.tn`'s own header: `!!id:"https://tson.io/2026/40/m/temporal.tn?sha256=3d516776324209f0406523dac4cc7bac85af0d530599de85a55cdc0b3ef77b20"` */
export const TEMPORAL_TN =
  '!!id:"https://tson.io/2026/40/m/temporal.tn?sha256=3d516776324209f0406523dac4cc7bac85af0d530599de85a55cdc0b3ef77b20"\n!!import:"https://tson.io/2026/40/m/meta.tn?sha256=291ddaf37566f9f084515d09626f1855d05f2cfb9413e3ce0073323f4933ddcd"\n@doc:"""\n  The TSON temporal library: `date`, `time`, `datetime`, `duration` and\n  `period`, each RFC 3339\'s. A schema imports it, or core.tn, to write them\n  ([TSON-DATA] §5.4, [TSON-SCHEMA] §5.5). numeric.tn\'s shared rules for bounds\n  and `multiple_of` apply.\n  """\n!schema {\n  @doc:"""\n    The temporal constructors, each named by its path, `temporal.date_type`.\n    """\n  temporal => !schema {\n    @doc:"""\n      The constructor of `date`: RFC 3339 `full-date`. An author refines the\n      instance: `recent => !date ^ { min: 2000-01-01 }`.\n      """\n    date_type => meta.atom & atom.specification & {\n      spec?: = "https://www.rfc-editor.org/rfc/rfc3339"\n      ( min: date | exclusive_min: date )?\n      ( max: date | exclusive_max: date )?\n    }\n\n    @doc:"""\n      The constructor of `time`: RFC 3339 `full-time`. The value is the time of\n      day in UTC, on [00:00:00, 24:00:00): the offset is a spelling, so\n      `10:00:00+01:00` and `09:00:00Z` are one value, and `23:30:00-02:00` is\n      `01:30:00Z`. A leap second, `23:59:60`, is refused.\n\n      `fraction_digits: N` admits a value that is a whole number of 10^-N\n      seconds, N at most 9. It constrains the value and not a spelling:\n      `12:00:00.500` is admitted under `fraction_digits: 1`, and is written\n      `12:00:00.5`.\n      """\n    time_type => meta.atom & atom.specification & {\n      spec?:            = "https://www.rfc-editor.org/rfc/rfc3339"\n      ( min: time | exclusive_min: time )?\n      ( max: time | exclusive_max: time )?\n      fraction_digits?: numeric.count\n    }\n\n    @doc:"""\n      The constructor of `datetime`: RFC 3339 `date-time`. The value is the\n      instant on the UTC timeline: the offset is a spelling, so\n      `2026-01-01T10:00:00+01:00` and `2026-01-01T09:00:00Z` are one value, and\n      `-00:00` is the same instant as `Z`. A leap second is refused.\n      `fraction_digits` is `time_type`\'s.\n      """\n    datetime_type => meta.atom & atom.specification & {\n      spec?:            = "https://www.rfc-editor.org/rfc/rfc3339"\n      ( min: datetime | exclusive_min: datetime )?\n      ( max: datetime | exclusive_max: datetime )?\n      fraction_digits?: numeric.count\n    }\n\n    @doc:"""\n      The constructor of `duration`. The value is a signed exact decimal number\n      of seconds: `PT90M`, `PT1H30M` and `P0DT5400S` are one value, and so are\n      `PT0S`, `P0D` and `-PT0S`. A day is 86400 s and a week 7 days.\n\n      The lexical form is RFC 3339 Appendix A\'s `duration` with an optional\n      leading `-`; a fraction on the seconds component only, written with `.`\n      (`PT0.5S`, never `PT1.5H`); any of D, H, M, S omitted, at least one\n      present and in order; and no Y or month-M component (`P1M` is a `period`,\n      a minute `PT1M`). `PnW` stands alone (`P1W2D` is an error).\n\n      The seconds component has at most nine fractional digits, and a magnitude\n      does not exceed 2^63 - 1 nanoseconds. A processor MUST represent every\n      value in that range and MUST reject one outside it whether or not its own\n      representation could hold it.\n\n      `fraction_digits` is `time_type`\'s. `multiple_of` is a step over the\n      seconds count: `PT15M` admits only quarter-hour values.\n      """\n    duration_type => meta.atom & atom.specification & {\n      spec?:            = "https://www.rfc-editor.org/rfc/rfc3339#appendix-A"\n      ( min: duration | exclusive_min: duration )?\n      ( max: duration | exclusive_max: duration )?\n      fraction_digits?: numeric.count\n      multiple_of?:     duration\n    }\n\n    @doc:"""\n      The constructor of `period`. The value is a signed integer number of\n      months: `P1Y` and `P12M` are one value, and so are `P0Y`, `P0M` and\n      `-P0M`. The lexical form is RFC 3339 Appendix A\'s `duration` restricted to\n      an optional leading `-`, then `P` with a Y component, an M component, or\n      both in that order: no fraction, no W or D component and no `T` part.\n      """\n    period_type => meta.atom & atom.specification & {\n      spec?:       = "https://www.rfc-editor.org/rfc/rfc3339#appendix-A"\n      ( min: period | exclusive_min: period )?\n      ( max: period | exclusive_max: period )?\n      multiple_of?: period\n    }\n  }\n\n  @doc:"A calendar date, `2026-01-31`."\n  @atom.ordering:TOTAL @atom.bounded:true\n  date => !temporal.date_type {}\n\n  @doc:"""\n    A time of day with a mandatory offset. Two spellings of one UTC time are one\n    value.\n    """\n  @atom.ordering:TOTAL @atom.bounded:true\n  time => !temporal.time_type {}\n\n  @doc:"""\n    A date and time with a mandatory offset: an instant, so two spellings of one\n    instant are one value.\n    """\n  @atom.ordering:TOTAL @atom.bounded:true\n  datetime => !temporal.datetime_type {}\n\n  @doc:"""\n    Elapsed time as an exact number of seconds, `PT1H30M`. It has no year or\n    month component: a calendar span is a `period`.\n    """\n  @atom.ordering:TOTAL @atom.bounded:true\n  duration => !temporal.duration_type {}\n\n  @doc:"A calendar span as a whole number of months, `P1Y6M`."\n  @atom.ordering:TOTAL @atom.bounded:false\n  period => !temporal.period_type {}\n}';

/** `spec/m/net.tn`'s own header: `!!id:"https://tson.io/2026/40/m/net.tn?sha256=80b8d1c1af70469b6513891498781454595202cdb3a49501b70b216b5108ea7d"` */
export const NET_TN =
  '!!id:"https://tson.io/2026/40/m/net.tn?sha256=80b8d1c1af70469b6513891498781454595202cdb3a49501b70b216b5108ea7d"\n!!import:"https://tson.io/2026/40/m/meta.tn?sha256=291ddaf37566f9f084515d09626f1855d05f2cfb9413e3ce0073323f4933ddcd"\n@doc:"""\n  The TSON network library: `email`, `ipv4`, `ipv6`, `cidr4`, `cidr6`, `mac`,\n  `hostname`, `host`, `media_type`, `uri`, `uri_reference` and `uuid`. A schema\n  imports it, or core.tn, to write them ([TSON-DATA] §5.5, [TSON-SCHEMA] §5.5).\n  """\n!schema {\n  @doc:"The network constructors, each named by its path, `net.ipv4_type`."\n  net => !schema {\n    @doc:"""\n      The constructor of `email` (RFC 5322). An address is its text as written.\n      """\n    email_type => unicode.text_type & atom.specification & {\n      spec?:          = "https://www.rfc-editor.org/rfc/rfc5322"\n      normalization?: = NONE\n    }\n\n    @doc:"""\n      The constructor of `ipv4`: RFC 3986\'s `IPv4address`, a dotted quad. An\n      address lies inside at least one `within` network, where any is given, and\n      inside no `excluding` network:\n      `private => !ipv4 ^ { within: ["10.0.0.0/8"] }`.\n      """\n    ipv4_type => meta.atom & atom.specification & {\n      spec?:      = "https://www.rfc-editor.org/rfc/rfc3986"\n      within?:    [cidr4]\n      excluding?: [cidr4]\n    }\n\n    @doc:"""\n      The constructor of `ipv6`: RFC 4291 §2.2 text, with no zone identifier.\n      `within` and `excluding` are as `ipv4_type`\'s.\n      """\n    ipv6_type => meta.atom & atom.specification & {\n      spec?:      = "https://www.rfc-editor.org/rfc/rfc4291"\n      within?:    [cidr6]\n      excluding?: [cidr6]\n    }\n\n    @doc:"""\n      The constructor of `cidr4`: an address, `/` and a prefix length.\n      `min_prefix` and `max_prefix` lie in 0-32. A value is a subnet of at least\n      one `within` network, where any is given, and overlaps no `excluding`\n      network. Ordering is by containment, and disjoint networks are\n      incomparable.\n      """\n    cidr4_type => meta.atom & atom.specification & {\n      spec?:       = "https://www.rfc-editor.org/rfc/rfc4632"\n      min_prefix?: numeric.count\n      max_prefix?: numeric.count\n      within?:     [cidr4]\n      excluding?:  [cidr4]\n    }\n\n    @doc:"""\n      The constructor of `cidr6`: as `cidr4_type`, with prefix lengths in 0-128.\n      """\n    cidr6_type => meta.atom & atom.specification & {\n      spec?:       = "https://www.rfc-editor.org/rfc/rfc4291"\n      min_prefix?: numeric.count\n      max_prefix?: numeric.count\n      within?:     [cidr6]\n      excluding?:  [cidr6]\n    }\n\n    @doc:"""\n      The constructor of `mac`. EUI-48: six hex octets, colon- or\n      hyphen-separated.\n      """\n    mac_type => meta.atom & atom.specification & {\n      spec?: = "https://www.rfc-editor.org/rfc/rfc9542"\n    }\n\n    @doc:"""\n      The constructor of `hostname`. A domain name: labels of ASCII letters,\n      digits and hyphens (RFC 1123 §2.1), or internationalized labels judged by\n      IDNA2008 (RFC 5890 to RFC 5893), written as U-labels or as their A-labels,\n      in any mix. `A`-`Z` read as `a`-`z`; nothing else is mapped, so uppercase\n      beyond ASCII, a U-label not in NFC and percent-encoding are not host\n      names. A label is at most 63 octets and the name at most 253, counted in\n      the A-label form; no label is empty, none begins or ends with `-`, and\n      there is no trailing `.`. The last label does not begin with a digit.\n\n      The value is the name: every spelling of one name is one value, and its\n      canonical text has each internationalized label as its U-label.\n      `allow_idn` false admits only names with no internationalized label, in\n      either spelling.\n      """\n    hostname_type => meta.atom & atom.specification & {\n      spec?:      = "https://www.rfc-editor.org/rfc/rfc5890"\n      allow_idn?: boolean ~ true\n    }\n\n    @doc:"""\n      The constructor of `host`. RFC 3987\'s `ihost` with a DNS name: a host name\n      as `hostname_type` has it, an IPv4 address in dotted-quad, or an IPv6\n      address, with or without the brackets a URI puts around one, and no zone\n      identifier.\n\n      The value is the name or the address, never both: a name compares by name,\n      an address by its octets, and an IPv4 address never equals an IPv6 one,\n      IPv4-mapped included. The canonical text is the member\'s: the name\'s\n      U-labels, the dotted-quad, or RFC 5952 text without brackets.\n      """\n    host_type => meta.atom & atom.specification & {\n      spec?: = "https://www.rfc-editor.org/rfc/rfc3987"\n    }\n\n    @doc:"""\n      The constructor of `media_type`. A media type (RFC 6838) and its\n      parameters (RFC 9110 §8.3.1): the type and subtype are RFC 6838 §4.2\'s\n      `restricted-name`, and each parameter is a token name, `=` and a token or\n      quoted-string value, after a `;` with optional whitespace around it.\n      Nothing beyond US-ASCII. A media range (`text/*`) is not a media type.\n\n      The value is the type, the subtype and a map of parameters: the type,\n      subtype and parameter names compare without ASCII case, a quoted value\n      equals its token form, parameter order carries no meaning and a repeated\n      name is a resolver error, and a parameter value keeps its case except\n      `charset`\'s, which folds. The canonical text is lowercase, with `charset`\n      folded and parameters sorted by name, each value a token where it is one,\n      joined by `;` without whitespace.\n\n      Parameters are admitted only where `allow_parameters` is set, as in\n      `content_type => !net.media_type_type { allow_parameters: true }`. `types`\n      lists the top-level types admitted. `suffixes` lists RFC 6839 structured\n      suffixes: a suffix admits a subtype ending `+` and the suffix, and the\n      subtype that is the suffix itself.\n      """\n    media_type_type => meta.atom & atom.specification & {\n      spec?:             = "https://www.rfc-editor.org/rfc/rfc6838"\n      allow_parameters?: boolean ~ false\n      types?:            [text]\n      suffixes?:         [text]\n    }\n\n    @doc:"""\n      The constructor of `uri` and `uri_reference`: RFC 3986\'s grammar,\n      US-ASCII, with `net.iri_type`\'s facets. Withdrawing `allow_fragment`\n      beside `allow_relative` leaves an absolute-URI (§4.3).\n      """\n    uri_type => unicode.text_type & atom.specification & {\n      spec?:           = "https://www.rfc-editor.org/rfc/rfc3986"\n      schemes?:        net.scheme_set\n      allow_relative?: boolean ~ true\n      allow_fragment?: boolean ~ true\n      normalization?:  = NONE\n    }\n\n    @doc:"""\n      The constructor of `uuid` (RFC 9562). `version` admits one UUID version:\n      `!uuid ^ { version: 4 }`.\n      """\n    uuid_type => meta.atom & atom.specification & {\n      spec?:    = "https://www.rfc-editor.org/rfc/rfc9562"\n      version?: numeric.count\n    }\n  }\n\n  @doc:"An email address (RFC 5322)."\n  @atom.ordering:NONE @atom.bounded:false\n  email => !net.email_type {}\n\n  @doc:"An IPv4 address, `192.0.2.1`."\n  @atom.ordering:TOTAL @atom.bounded:true\n  ipv4 => !net.ipv4_type {}\n\n  @doc:"An IPv6 address (RFC 4291 §2.2), with no zone identifier."\n  @atom.ordering:TOTAL @atom.bounded:true\n  ipv6 => !net.ipv6_type {}\n\n  @doc:"An IPv4 network, an address and a prefix length: `10.0.0.0/8`."\n  @atom.ordering:PARTIAL @atom.bounded:false\n  cidr4 => !net.cidr4_type {}\n\n  @doc:"An IPv6 network, an address and a prefix length."\n  @atom.ordering:PARTIAL @atom.bounded:false\n  cidr6 => !net.cidr6_type {}\n\n  @doc:"A MAC address (EUI-48)."\n  @atom.ordering:NONE @atom.bounded:false\n  mac => !net.mac_type {}\n\n  @doc:"""\n    An Internet host name. `Example.COM` and `example.com` are one value, and so\n    are `xn--bcher-kva.example` and `bücher.example`.\n    """\n  @atom.ordering:NONE @atom.bounded:false\n  hostname => !net.hostname_type {}\n\n  @doc:"A host: a `hostname`, an IPv4 address or an IPv6 address."\n  @atom.ordering:NONE @atom.bounded:false\n  host => !net.host_type {}\n\n  @doc:"A media type without parameters: `text/html`, `application/ld+json`."\n  @atom.ordering:NONE @atom.bounded:false\n  media_type => !net.media_type_type {}\n\n  @doc:"A URI-reference (RFC 3986 §4.1): a URI or a relative reference."\n  @atom.ordering:NONE @atom.bounded:false\n  uri_reference => !net.uri_type {}\n\n  @doc:"A URI (RFC 3986 §3): the scheme is required."\n  @atom.ordering:NONE @atom.bounded:false\n  uri => !uri_reference ^ { allow_relative: false }\n\n  @doc:"A UUID (RFC 9562)."\n  @atom.ordering:NONE @atom.bounded:false\n  uuid => !net.uuid_type {}\n}\n';

/** `spec/m/core.tn`'s own header: `!!id:"https://tson.io/2026/40/m/core.tn?sha256=00eaf2174c7ba05510ce8410a4b7577bf6fd4bf6db8f099a7c8ec02edd053241"` */
export const CORE_TN =
  '!!id:"https://tson.io/2026/40/m/core.tn?sha256=00eaf2174c7ba05510ce8410a4b7577bf6fd4bf6db8f099a7c8ec02edd053241"\n!!import:"https://tson.io/2026/40/m/numeric.tn?sha256=0337c18854a0e689ce53d9cae47e1cfd32bd54026acd6a3bac9abae358cb86f7"\n!!import:"https://tson.io/2026/40/m/temporal.tn?sha256=3d516776324209f0406523dac4cc7bac85af0d530599de85a55cdc0b3ef77b20"\n!!import:"https://tson.io/2026/40/m/net.tn?sha256=80b8d1c1af70469b6513891498781454595202cdb3a49501b70b216b5108ea7d"\n@doc:"""\n  TSON core: every bundled type in one import. It imports numeric.tn,\n  temporal.tn and net.tn, and declares the author annotations, none of which\n  changes what a type admits ([TSON-SCHEMA] §6, §9).\n  """\n!schema {\n  @doc:"""\n    Marks a definition or field as deprecated, written bare before it:\n    `@deprecated`.\n    """\n  deprecated => @meta.annotation void\n\n  @doc:"A short human-readable name for a definition or field."\n  title => @meta.annotation text\n\n  @doc:"""\n    A note for a schema\'s maintainers, which a documentation tool leaves out.\n    """\n  comment => @meta.annotation text\n\n  @doc:"""\n    Example values for a definition or field. Each is the text a reader is\n    shown, conventionally the value in TSON notation, and nothing parses or\n    checks one.\n    """\n  examples => @meta.annotation [text]\n\n  @doc:"Marks a field a consumer may read but not write."\n  read_only => @meta.annotation void\n\n  @doc:"Marks a field a consumer may write but not read."\n  write_only => @meta.annotation void\n}\n';

/** `spec/m/policy.tn`'s own header: `!!id:"https://tson.io/2026/40/m/policy.tn?sha256=ffcecb04bf6be35c8e2c93375bf2c1bb1d09603f874823495ed7d8cf107fb408"` */
export const POLICY_TN =
  '!!id:"https://tson.io/2026/40/m/policy.tn?sha256=ffcecb04bf6be35c8e2c93375bf2c1bb1d09603f874823495ed7d8cf107fb408"\n!!import:"https://tson.io/2026/40/m/meta.tn?sha256=291ddaf37566f9f084515d09626f1855d05f2cfb9413e3ce0073323f4933ddcd"\n@doc:"""\n  The TSON processor policy: what a processor admits as a name and what it\n  spends ([TSON-DATA] §8.2, §9.1; [TSON-SCHEMA] §11.5). A policy is the\n  deployment\'s, never a schema\'s: no document names, imports or selects the\n  policy it is judged under. A deployment that writes its policy down writes a\n  data document of type `policy.processor`. A script is named by its Unicode\n  Script property value alias (UAX #24), `Latin`, `Cyrillic`, `Han`.\n  """\n!schema {\n  policy => !schema {\n    @doc:"UTS #39 §5.2\'s restriction levels, strictest first."\n    restriction_level => !enum [\n      ASCII_ONLY SINGLE_SCRIPT HIGHLY_RESTRICTIVE MODERATELY_RESTRICTIVE MINIMALLY_RESTRICTIVE UNRESTRICTED\n    ]\n\n    @doc:"""\n      The token policy: the level over each whole token. Each entry of\n      `permitting` is a script combination admitted over the level (UTS #39\n      §5.2).\n      """\n    token_policy => { level: policy.restriction_level  permitting: [[text]] }\n\n    @doc:"""\n      The identifier policy. `per_segment` applies the level to each segment of\n      a name rather than to the whole of it, and `skeleton_distinctness` forbids\n      two names in one scope sharing a UTS #39 skeleton.\n      """\n    identifier_policy => {\n      level: policy.restriction_level\n      per_segment: boolean\n      skeleton_distinctness: boolean\n      permitting: [[text]]\n    }\n\n    @doc:"""\n      One resource limit: a count, a depth or a size. A processor that holds a\n      limit in a narrower type caps a larger value at the widest it holds.\n      """\n    limit => !int64 ^ { min: 1 }\n\n    @doc:"""\n      What a processor will spend reading one document and resolving one schema.\n      Each default is the specification\'s value, and a deployment writes only\n      what it raises. A limit refusal names the limit and the threshold, and is\n      not a verdict on the document ([TSON-DATA] §9.1, [TSON-SCHEMA] §11.5).\n      """\n    limits => {\n      max_depth?:                  policy.limit ~ 64\n      max_token_length?:           policy.limit ~ 1048576\n      max_text_length?:            policy.limit ~ 1048576\n      max_numeric_literal_length?: policy.limit ~ 4096\n      max_binary_size?:            policy.limit ~ 16777216\n      max_document_size?:          policy.limit ~ 16777216\n      max_elements?:               policy.limit ~ 1048576\n      max_entries?:                policy.limit ~ 1048576\n      max_fields?:                 policy.limit ~ 65536\n      max_annotations?:            policy.limit ~ 64\n      max_values?:                 policy.limit ~ 16777216\n      max_import_closure?:         policy.limit ~ 64\n      max_schema_entries?:         policy.limit ~ 65536\n      max_alias_chain?:            policy.limit ~ 64\n      max_supertype_chain?:        policy.limit ~ 64\n      max_wait_depth?:             policy.limit ~ 64\n    }\n\n    @doc:"""\n      The policy a processor judges a document under. `unicode_data_version` is\n      the UCD release whose tables the name rules read: a report states it, and\n      a deployment\'s own policy document leaves it out.\n      """\n    processor => {\n      identifier_policy: policy.identifier_policy\n      token_policy: policy.token_policy\n      unicode_data_version?: text\n      limits: policy.limits\n    }\n  }\n}\n';
